#!/usr/bin/env python3
import pandas as pd
import matplotlib.pyplot as plt
import os

def main():
    # Path to the CSV file generated by SMC
    csv_path = os.path.expanduser('~/robust_nonlinear_controller/trajectory_data.csv')
    
    if not os.path.exists(csv_path):
        print(f"Error: File {csv_path} not found. Run the simulation first.")
        return

    # Load data
    data = pd.read_csv(csv_path)

    # Create the plot
    plt.figure(figsize=(10, 8))
    
    # Plot desired trajectory (Black dashed line)
    # Using .to_numpy() to avoid pandas/matplotlib compatibility issues
    plt.plot(data['x_des'].to_numpy(), data['y_des'].to_numpy(), 'k--', label='Desired Trajectory ($h_d$)', linewidth=2)
    
    # Plot real robot trajectory (Red solid line)
    plt.plot(data['x_real'].to_numpy(), data['y_real'].to_numpy(), 'r-', label='Real TurtleBot Trajectory ($h$)', linewidth=1.5)

    # Start marker
    plt.plot(data['x_real'].iloc[0], data['y_real'].iloc[0], 'go', label='Start Point', markersize=8)

    # Plot configuration
    plt.title("Trajectory Tracking with Sliding Mode Control (SMC)")
    plt.xlabel("X Position (m)")
    plt.ylabel("Y Position (m)")
    plt.axis('equal') # Keep aspect ratio equal to prevent distortion
    plt.grid(True, linestyle=':', alpha=0.7)
    plt.legend()
    
    # Save and display
    plt.savefig('trajectory_result.png', dpi=300, bbox_inches='tight')
    print("Plot saved as 'trajectory_result.png'")
    plt.show()

if __name__ == '__main__':
    main()